            for ingredient in ingredients[:2]:
                clean_ing = sanitize_input(ingredient)
                query = f"magical folklore and symbolic meaning of {clean_ing}"
                results = list(ddgs.text(query, max_results=2))
                lore_context += f"\nLore for {ingredient}:\n"
                for r in results:
                    # Restored HTML tag sanitization from Turn 3
                    snippet = re.sub('<[^<]+?>', '', r.get('body', ''))
                    lore_context += f"- {snippet}\n"
    except Exception:
        return "No additional folklore found."
    return lore_context

@app.route('/generate-spell', methods=['POST'])
@limiter.limit("5 per minute")
def generate_spell():
    raw_ingredients = []

    # 1. Support legacy JSON input (Turn 3 compatibility)
    if request.is_json:
        data = request.get_json()
        raw_ingredients = data.get('ingredients', [])

    # 2. Support new File/Form Uploads
    else:
        recipe_text = ""
        if 'recipe_file' in request.files:
            file = request.files['recipe_file']
            if file.filename.lower().endswith('.pdf'):
                recipe_text = extract_text_from_pdf(file)
            elif file.filename.lower().endswith(('.png', '.jpg', '.jpeg')):
                recipe_text = extract_text_from_image(file)

        if not recipe_text:
            recipe_text = request.form.get('recipe_text', '')

        if recipe_text and len(recipe_text) > 10:
            try:
                # AI cleans messy OCR text into ingredients
                extraction = openai.ChatCompletion.create(
                    model="gpt-3.5-turbo",
                    messages=[
                        {"role": "system", "content": "Extract only the main ingredients from this recipe text as a comma-separated list."},
                        {"role": "user", "content": recipe_text[:2000]}
                    ]
                )
                raw_ingredients = extraction.choices[0].message.content.split(',')
            except Exception: pass

    if not raw_ingredients:
        return jsonify({"error": "Could not extract ingredients. Provide a file or text."}), 400

    ingredients = [sanitize_input(str(i))[:30] for i in raw_ingredients[:5]]

    try:
